insert into topic_contents (topic_id, summary, content_md, example_question) values ('f046e8ff-0d47-47fa-add9-45a27a151b63', 'Hukuk kurallarını diğer toplumsal düzen kurallarından (ahlak, din, görgü) ayıran temel özellik olan devlet gücüyle desteklenen müeyyide (yaptırım) kavramı; kamu-özel hukuk ayrımı ve normlar hiyerarşisi bu konunun omurgasını oluşturur.', '## Hukuk Kuralının Ayırt Edici Özelliği: Müeyyide
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('3b756507-60fb-4ff3-8ba3-43aa8ddac429', 'f046e8ff-0d47-47fa-add9-45a27a151b63', 'kolay'::difficulty_level, 'Hukuk kurallarını ahlak kurallarından ayıran en temel özellik aşağıdakilerden hangisidir?', 'Hukuk kuralının ayırt edici özelliğini bilir.', 'Hukuk kurallarına uyulmadığında uygulanan yaptırımın DEVLET GÜCÜYLE desteklenmesi, onu ahlak kurallarından ayıran temel özelliktir (B doğru); ahlak kurallarının yaptırımı toplumsal ayıplama ve vicdani rahatsızlıktır, devlet gücüyle desteklenmez. Yazılı olma (A) tüm hukuk kuralları için geçerli değildir (örf ve adet hukuku yazısızdır). Genellik (C) ve süreklilik (D) hem hukuk hem ahlak kuralında bulunabilir. Değişkenlik (E) ayırt edici bir özellik değildir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b756507-60fb-4ff3-8ba3-43aa8ddac429', 'Yazılı bir metne dayanması', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b756507-60fb-4ff3-8ba3-43aa8ddac429', 'Yaptırımının devlet gücüyle desteklenmesi', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b756507-60fb-4ff3-8ba3-43aa8ddac429', 'Herkes için geçerli (genel) olması', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b756507-60fb-4ff3-8ba3-43aa8ddac429', 'Uzun süre değişmeden uygulanması', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3b756507-60fb-4ff3-8ba3-43aa8ddac429', 'Toplumdan topluma farklılık göstermesi', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('2d3965a4-91ef-4fc9-a3c6-f98555d92fce', 'f046e8ff-0d47-47fa-add9-45a27a151b63', 'orta'::difficulty_level, 'Aşağıdaki hukuk dallarından hangisi özel hukuk kapsamında değerlendirilir?', 'Kamu hukuku ile özel hukuku ayırt eder.', 'Borçlar hukuku, eşit taraflar (alacaklı-borçlu) arasındaki ilişkileri düzenlediği için özel hukuk kapsamındadır (D doğru). Anayasa hukuku (A), ceza hukuku (B), idare hukuku (C) ve vergi hukuku (E) ise devletin taraf olduğu ve üstün-taraf ilişkisinin bulunduğu kamu hukuku dallarıdır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2d3965a4-91ef-4fc9-a3c6-f98555d92fce', 'Anayasa hukuku', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2d3965a4-91ef-4fc9-a3c6-f98555d92fce', 'Ceza hukuku', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2d3965a4-91ef-4fc9-a3c6-f98555d92fce', 'İdare hukuku', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2d3965a4-91ef-4fc9-a3c6-f98555d92fce', 'Borçlar hukuku', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2d3965a4-91ef-4fc9-a3c6-f98555d92fce', 'Vergi hukuku', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('64479fb6-5457-4258-b5ac-ecca4a783644', 'f046e8ff-0d47-47fa-add9-45a27a151b63', 'zor'::difficulty_level, 'Türk hukuk sistemindeki normlar hiyerarşisiyle ilgili aşağıdaki çıkarımlardan hangisi doğrudur?', 'Normlar hiyerarşisini güncel mevzuata göre değerlendirir.', '2017 Anayasa değişikliği sonrasında KHK (Kanun Hükmünde Kararname) çıkarma yetkisi kaldırılmış, yerine Cumhurbaşkanlığı kararnamesi getirilmiştir; bir yönetmelik Cumhurbaşkanlığı kararnamesine aykırı olamaz (D doğru). A yanlıştır, kanun Anayasaya değil Anayasa kanuna üstündür (Anayasa en üsttedir). B yanlıştır, KHK artık normal dönemde çıkarılamaz. C yanlıştır, yönetmelik hiyerarşinin en altındadır, kanunun üstünde değildir. E yanlıştır, Cumhurbaşkanlığı kararnamesi kanunla aynı düzeyde değil kanunun ALTINDA yer alır ve kanuna aykırı olamaz.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('64479fb6-5457-4258-b5ac-ecca4a783644', 'Anayasa, kanunlara göre daha alt bir normdur', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('64479fb6-5457-4258-b5ac-ecca4a783644', 'KHK (Kanun Hükmünde Kararname), günümüzde de olağan dönemde çıkarılabilen bir norm türüdür', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('64479fb6-5457-4258-b5ac-ecca4a783644', 'Yönetmelik, kanunun üstünde yer alan bir normdur', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('64479fb6-5457-4258-b5ac-ecca4a783644', 'Bir yönetmelik, Cumhurbaşkanlığı kararnamesine aykırı hüküm içeremez', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('64479fb6-5457-4258-b5ac-ecca4a783644', 'Cumhurbaşkanlığı kararnamesi, kanunla tamamen aynı düzeyde bir norm olup kanuna aykırı olabilir', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('2484db10-1d02-4dfb-9663-4d36c9b03c8f', 'f046e8ff-0d47-47fa-add9-45a27a151b63', 'orta'::difficulty_level, 'Bir yörede yıllardan beri uygulanan ve toplum tarafından hukuki bir zorunluluk olarak benimsenen, ancak hiçbir yazılı metinde yer almayan bir kural, devlet tarafından tanınıp uygulandığında hukukun hangi kaynağı içinde değerlendirilir?', 'Hukukun yazısız kaynağını (örf ve adet hukuku) tanır.', 'Yazılı bir metne dayanmayan ama toplumda hukuki bir zorunluluk inancıyla uzun süredir uygulanan ve devlet tarafından tanınan kurallar örf ve adet hukukunu oluşturur; bu, hukukun YAZISIZ bir kaynağıdır (B doğru). Kanun (A), yönetmelik (C) ve Cumhurbaşkanlığı kararnamesi (D) yazılı kaynaklardır ve resmi bir metne dayanır. Mahkeme içtihadı (E) farklı bir kaynak türüdür, doğrudan bu tanıma uymaz.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2484db10-1d02-4dfb-9663-4d36c9b03c8f', 'Kanun', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2484db10-1d02-4dfb-9663-4d36c9b03c8f', 'Örf ve adet hukuku', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2484db10-1d02-4dfb-9663-4d36c9b03c8f', 'Yönetmelik', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2484db10-1d02-4dfb-9663-4d36c9b03c8f', 'Cumhurbaşkanlığı kararnamesi', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('2484db10-1d02-4dfb-9663-4d36c9b03c8f', 'Mahkeme içtihadı', false, 4);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('86ae4cc1-2323-4a43-8448-b1fa4daf514e', '1982 Anayasası''nın sert (katı) niteliği, değiştirilemez hükümleri (madde 1-2-3), anayasa değişikliği usulü ve 2017''de Cumhurbaşkanlığı hükümet sistemine geçişin getirdiği değişiklikler bu konunun temel omurgasıdır.', '## 1982 Anayasası''nın Genel Nitelikleri
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('97c95be5-dd47-49fc-8470-f9b448b51d09', '86ae4cc1-2323-4a43-8448-b1fa4daf514e', 'kolay'::difficulty_level, '1982 Anayasası''nın 1, 2 ve 3. maddeleriyle ilgili aşağıdakilerden hangisi doğrudur?', 'Anayasanın değiştirilemez hükümlerini bilir.', 'Anayasanın ilk üç maddesi (devletin şekli, nitelikleri, bayrak-başkent-dil gibi temel unsurlar) değiştirilemez ve değiştirilmesi teklif dahi edilemez (C doğru). A yanlıştır, tam tersine bu maddeler diğer maddelerden daha SIKI korunur. B yanlıştır, sadece TBMM kararıyla değil hiçbir usulle değiştirilemezler. D ve E gerçeği yansıtmayan, konuyla ilgisiz iddialardır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('97c95be5-dd47-49fc-8470-f9b448b51d09', 'Bu maddeler diğer maddelerle aynı usulle, herhangi bir kısıtlama olmadan değiştirilebilir', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('97c95be5-dd47-49fc-8470-f9b448b51d09', 'Bu maddeler yalnızca TBMM''nin basit çoğunluk kararıyla değiştirilebilir', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('97c95be5-dd47-49fc-8470-f9b448b51d09', 'Bu maddeler değiştirilemez ve değiştirilmesi teklif dahi edilemez', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('97c95be5-dd47-49fc-8470-f9b448b51d09', 'Bu maddeler yalnızca Anayasa Mahkemesi kararıyla değiştirilebilir', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('97c95be5-dd47-49fc-8470-f9b448b51d09', 'Bu maddeler halkoylamasına gerek kalmadan Cumhurbaşkanı kararıyla değiştirilebilir', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e62344fc-513a-430a-8642-65c6a207a347', '86ae4cc1-2323-4a43-8448-b1fa4daf514e', 'orta'::difficulty_level, '2017 Anayasa değişikliği ile Türkiye''de yönetim sistemiyle ilgili aşağıdaki değişikliklerden hangisi gerçekleşmiştir?', 'Cumhurbaşkanlığı hükümet sistemine geçişin temel özelliklerini bilir.', '2017 Anayasa değişikliğiyle Başbakanlık ve Bakanlar Kurulu kaldırılmış, yürütme yetkisi tek başına Cumhurbaşkanına verilmiştir (C doğru). A ve B yanlıştır, tam tersi bir değişiklik yapılmıştır (parlamenter sistemden çıkılmış, güçler ayrılığı klasik anlamda korunmamıştır). D yanlıştır, TBMM üye sayısı 550''den 600''e ÇIKARILMIŞTIR, düşürülmemiştir. E yanlıştır, aksine Cumhurbaşkanının bir siyasi partiyle ilişkisini SÜRDÜREBİLMESİNE izin verilmiştir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e62344fc-513a-430a-8642-65c6a207a347', 'Parlamenter sistem güçlendirilerek Başbakanlığın yetkileri artırılmıştır', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e62344fc-513a-430a-8642-65c6a207a347', 'Kuvvetler ayrılığı ilkesi daha da katılaştırılarak yürütme iki başlı hâle getirilmiştir', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e62344fc-513a-430a-8642-65c6a207a347', 'Başbakanlık ve Bakanlar Kurulu kaldırılarak yürütme yetkisi tek başına Cumhurbaşkanına verilmiştir', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e62344fc-513a-430a-8642-65c6a207a347', 'TBMM üye tam sayısı 600''den 550''ye düşürülmüştür', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e62344fc-513a-430a-8642-65c6a207a347', 'Cumhurbaşkanının herhangi bir siyasi partiyle ilişkisinin kesilmesi zorunlu hâle getirilmiştir', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('449a48ee-654c-4bf1-8043-76d8147e19ab', '86ae4cc1-2323-4a43-8448-b1fa4daf514e', 'zor'::difficulty_level, 'TBMM''de bir anayasa değişikliği teklifi üye tam sayısının 3/5''i ile 2/3''ü arasında bir oranla (örneğin 3/5''ten fazla ama 2/3''ten az bir oyla) kabul edilmiştir. Bu durumda izlenecek yol aşağıdakilerden hangisidir?', 'Anayasa değişikliği usulünün oran aralıklarına göre sonuçlarını bilir.', 'Bir anayasa değişikliği teklifi üye tam sayısının 3/5''i ile 2/3''ü arasında bir oranla kabul edilirse, Cumhurbaşkanı bu değişikliği halkoyuna (referanduma) sunabilir veya tekrar görüşülmek üzere TBMM''ye geri gönderebilir (C doğru). A yanlıştır, bu durumda değişiklik otomatik olarak yürürlüğe girmez, halkoyuna sunulma ihtimali vardır. B yanlıştır, teklif reddedilmiş sayılmaz, kabul edilmiştir; sadece belirli bir prosedür izlenir. D ve E bu duruma özgü doğru prosedürler değildir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('449a48ee-654c-4bf1-8043-76d8147e19ab', 'Değişiklik hiçbir işleme gerek kalmadan doğrudan yürürlüğe girer', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('449a48ee-654c-4bf1-8043-76d8147e19ab', 'Teklif otomatik olarak reddedilmiş sayılır', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('449a48ee-654c-4bf1-8043-76d8147e19ab', 'Cumhurbaşkanı bu değişikliği halkoyuna sunabilir veya tekrar görüşülmek üzere TBMM''ye geri gönderebilir', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('449a48ee-654c-4bf1-8043-76d8147e19ab', 'Değişiklik doğrudan Anayasa Mahkemesi''nin onayına sunulur', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('449a48ee-654c-4bf1-8043-76d8147e19ab', 'Değişiklik yalnızca bir sonraki milletvekili genel seçiminden sonra yürürlüğe girebilir', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('738f4a6a-ece0-4bfd-928b-63a4ad7bb779', '86ae4cc1-2323-4a43-8448-b1fa4daf514e', 'orta'::difficulty_level, 'Anayasa Mahkemesi''nin başlıca görevlerinden biri olan "norm denetimi" ile ilgili aşağıdakilerden hangisi doğrudur?', 'Anayasa Mahkemesi''nin norm denetimi görevini açıklar.', 'Anayasa Mahkemesi, kanunların, Cumhurbaşkanlığı kararnamelerinin ve TBMM İçtüzüğü''nün Anayasaya şekil ve esas bakımından uygunluğunu denetler (D doğru). Yönetmelikler (A) bu denetimin konusu değildir, onların denetimi idari yargının (Danıştay) görevidir. Anayasa Mahkemesi milletvekili genel seçimlerini (B) değil, Yüksek Seçim Kurulu bu seçimleri yönetir. Uluslararası antlaşmaların Anayasaya uygunluğu (C) Anayasa Mahkemesi''nin denetim alanına girmez (usulüne göre yürürlüğe konulan antlaşmalar hakkında Anayasaya aykırılık iddiasıyla başvurulamaz). Cumhurbaşkanının cezai sorumluluğu (E) ayrı bir konu olan Yüce Divan yargılamasıyla ilgilidir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('738f4a6a-ece0-4bfd-928b-63a4ad7bb779', 'Yönetmeliklerin Anayasaya uygunluğunu denetler', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('738f4a6a-ece0-4bfd-928b-63a4ad7bb779', 'Milletvekili genel seçimlerinin sonuçlarını ilan eder', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('738f4a6a-ece0-4bfd-928b-63a4ad7bb779', 'Usulüne göre yürürlüğe konulmuş uluslararası antlaşmaların Anayasaya uygunluğunu denetler', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('738f4a6a-ece0-4bfd-928b-63a4ad7bb779', 'Kanunların, Cumhurbaşkanlığı kararnamelerinin ve TBMM İçtüzüğü''nün Anayasaya uygunluğunu denetler', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('738f4a6a-ece0-4bfd-928b-63a4ad7bb779', 'Cumhurbaşkanının günlük idari işlemlerini onaylar', false, 4);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('37c6d817-c011-4012-9f18-b651bf8b022e', 'Kuvvetler ayrılığı ilkesi çerçevesinde yasama (TBMM), yürütme (Cumhurbaşkanı) ve yargı (bağımsız mahkemeler-HSK) organlarının güncel (2017 sonrası) yapısı ve işleyişi bu konunun temelini oluşturur.', '## Yasama: TBMM
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e84980f8-688f-4ac3-aa10-9654cf3af7f7', '37c6d817-c011-4012-9f18-b651bf8b022e', 'kolay'::difficulty_level, '2017 Anayasa değişikliği sonrasında TBMM üye tam sayısı kaça çıkarılmıştır?', 'TBMM''nin güncel üye sayısını bilir.', '2017 Anayasa değişikliğiyle TBMM üye tam sayısı 550''den 600''e çıkarılmıştır (D doğru). Diğer seçenekler (A, B, C, E) güncel mevzuata uymayan, yanlış rakamlardır.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e84980f8-688f-4ac3-aa10-9654cf3af7f7', '500', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e84980f8-688f-4ac3-aa10-9654cf3af7f7', '550', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e84980f8-688f-4ac3-aa10-9654cf3af7f7', '450', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e84980f8-688f-4ac3-aa10-9654cf3af7f7', '600', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e84980f8-688f-4ac3-aa10-9654cf3af7f7', '650', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('c2733bc7-9e6f-4d1a-8114-4459334dc153', '37c6d817-c011-4012-9f18-b651bf8b022e', 'orta'::difficulty_level, 'Cumhurbaşkanlığı hükümet sisteminde Cumhurbaşkanının seçilme süresi ve tekrar seçilme sınırıyla ilgili aşağıdakilerden hangisi doğrudur?', 'Cumhurbaşkanının görev süresi ve seçilme sınırlarını bilir.', 'Cumhurbaşkanı halk tarafından 5 yıllığına seçilir ve bir kişi en fazla iki defa Cumhurbaşkanı seçilebilir; ancak ikinci döneminde TBMM''nin seçimlerin yenilenmesine karar vermesi hâlinde üçüncü kez aday olabilir (D doğru). A ve B rakamsal olarak yanlıştır (4 yıl değil 5 yıldır, sınırsız değil en fazla iki defadır). C yanlıştır, TBMM tarafından değil doğrudan halk tarafından seçilir. E, üç dönemin kesin bir kural olduğunu iddia ettiği için yanlıştır — üçüncü dönem yalnızca istisnai bir durumda mümkündür.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c2733bc7-9e6f-4d1a-8114-4459334dc153', '4 yıllığına seçilir ve sınırsız sayıda yeniden seçilebilir', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c2733bc7-9e6f-4d1a-8114-4459334dc153', '5 yıllığına seçilir ve sınırsız sayıda yeniden seçilebilir', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('c2733bc7-9e6f-4d1a-8114-4459334dc153', '5 yıllığına, TBMM tarafından seçilir', false, 2);
