insert into question_choices (question_id, choice_text, is_correct, order_index) values ('ad03f7e1-9e4f-4e4d-b41a-1743604f0611', 'I, II ve III', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('1b4ed332-5091-4c04-b714-323ca588f8aa', '37c6d817-c011-4012-9f18-b651bf8b022e', 'orta'::difficulty_level, 'Hakimler ve Savcılar Kurulu (HSK) ile ilgili aşağıdakilerden hangisi doğrudur?', 'HSK''nın görevlerini ve yargı bağımsızlığındaki rolünü bilir.', 'HSK, hakim ve savcıların atanması, terfi ettirilmesi ve disiplin işlemleri gibi mesleki konularını yürüterek yargı bağımsızlığının kurumsal güvencesini oluşturur (C doğru). A yanlıştır, kanunların Anayasaya uygunluğunu Anayasa Mahkemesi denetler, HSK değil. B yanlıştır, HSK yasama organı değildir, TBMM''ye bağlı bir yapı değildir. D yanlıştır, bütçeyi TBMM görüşüp kabul eder. E yanlıştır, milletvekili seçimlerini Yüksek Seçim Kurulu (YSK) yönetir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1b4ed332-5091-4c04-b714-323ca588f8aa', 'Kanunların Anayasaya uygunluğunu denetler', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1b4ed332-5091-4c04-b714-323ca588f8aa', 'TBMM''ye bağlı bir yasama organı alt birimidir', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1b4ed332-5091-4c04-b714-323ca588f8aa', 'Hakim ve savcıların atanması, terfisi ve disiplin işlerini yürütür', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1b4ed332-5091-4c04-b714-323ca588f8aa', 'Devlet bütçesini görüşüp kabul eder', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('1b4ed332-5091-4c04-b714-323ca588f8aa', 'Milletvekili genel seçimlerini yönetir', false, 4);
insert into topics (id, subject_id, name, slug, kazanim_text, weight, order_index) values ('a761a66c-9aa8-45fe-a865-b4833c71d0b2', 'a9ee39e3-e35c-4ff0-885a-4af773855d4d', 'Temel Hak ve Özgürlükler', 'temel-hak-ve-ozgurlukler', 'Anayasada güvence altına alınan temel hak ve özgürlüklerin sınıflandırılmasını ve sınırlandırılma esaslarını açıklar.', 1.0, 4);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('a761a66c-9aa8-45fe-a865-b4833c71d0b2', 'Temel hak ve özgürlüklerin kişi hakları, sosyal-ekonomik haklar ve siyasi haklar olarak sınıflandırılması; hakların ancak kanunla ve ölçülülük ilkesine uygun biçimde sınırlandırılabilmesi bu konunun omurgasıdır.', '## Hakların Sınıflandırılması
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('3e24c677-29e5-4c21-be49-c2efd6e1860d', 'a761a66c-9aa8-45fe-a865-b4833c71d0b2', 'kolay'::difficulty_level, 'Yaşama hakkı ve özel hayatın gizliliği gibi haklar, hangi hak kategorisinde yer alır ve devletten ne beklenir?', 'Kişi haklarının niteliğini ve devletten beklenen edim türünü bilir.', 'Yaşama hakkı ve özel hayatın gizliliği kişi haklarıdır ve bu haklardan devletin beklenmesi gereken şey MÜDAHALE ETMEMESİDİR (negatif edim) (B doğru). Bu haklar için devletten aktif bir hizmet sunması (A) beklenmez; bu, sosyal-ekonomik hakların özelliğidir. Bu haklar siyasi haklarla (C) veya yönetime katılımla (D, E) ilgili değildir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e24c677-29e5-4c21-be49-c2efd6e1860d', 'Sosyal-ekonomik haklardır; devletin aktif hizmet sunmasını gerektirir', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e24c677-29e5-4c21-be49-c2efd6e1860d', 'Kişi haklarıdır; devletin bu alana müdahale etmemesini gerektirir', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e24c677-29e5-4c21-be49-c2efd6e1860d', 'Siyasi haklardır; yönetime katılımı sağlar', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e24c677-29e5-4c21-be49-c2efd6e1860d', 'Kişi haklarıdır; devletin doğrudan maddi yardım sağlamasını gerektirir', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('3e24c677-29e5-4c21-be49-c2efd6e1860d', 'Bu haklar hiçbir kategoriye girmez', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('b9400d46-bfb8-4157-9fae-b8f5de69ad4f', 'a761a66c-9aa8-45fe-a865-b4833c71d0b2', 'orta'::difficulty_level, 'Anayasanın 13. maddesine göre temel hak ve özgürlüklerin sınırlandırılmasıyla ilgili aşağıdakilerden hangisi yanlıştır?', 'Hakların sınırlandırılma esaslarını (madde 13) bilir.', 'Temel hak ve özgürlükler ancak KANUNLA sınırlanabilir; bir yönetmelikle sınırlanabileceği iddiası (D) yanlıştır ve sorunun cevabıdır. Sınırlamanın Anayasanın sözüne ve ruhuna uygun olması (A), demokratik toplum düzeninin gereklerine aykırı olmaması (B), ölçülülük ilkesine uygun olması (C) ve hakkın özüne dokunulamaması (E) doğru ilkelerdir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b9400d46-bfb8-4157-9fae-b8f5de69ad4f', 'Sınırlama Anayasanın sözüne ve ruhuna aykırı olamaz', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b9400d46-bfb8-4157-9fae-b8f5de69ad4f', 'Sınırlama demokratik toplum düzeninin gereklerine aykırı olamaz', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b9400d46-bfb8-4157-9fae-b8f5de69ad4f', 'Sınırlama ölçülülük ilkesine uygun olmalıdır', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b9400d46-bfb8-4157-9fae-b8f5de69ad4f', 'Temel hak ve özgürlükler bir yönetmelikle de sınırlanabilir', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('b9400d46-bfb8-4157-9fae-b8f5de69ad4f', 'Sınırlama hakkın özüne dokunamaz', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('564c16b8-956c-4b39-9ecc-efa298aadb94', 'a761a66c-9aa8-45fe-a865-b4833c71d0b2', 'zor'::difficulty_level, 'Olağanüstü hal ilan edilen bir dönemde, savaş hukukuna uygun fiiller sonucu meydana gelen ölümler dışında, aşağıdaki haklardan hangisine yönelik bir sınırlama Anayasa''ya göre YAPILAMAZ?', 'Olağanüstü hallerde dokunulamayan çekirdek hakları (madde 15) bilir.', 'Anayasanın 15. maddesine göre, olağanüstü hallerde bile kişinin yaşama hakkına ve maddi-manevi varlığının bütünlüğüne dokunulamaz (savaş hukukuna uygun fiiller sonucu ölümler hariç) (C doğru). Seyahat özgürlüğü (A), toplantı ve gösteri yürüyüşü hakkı (B), basın özgürlüğü (D) ve mülkiyet hakkı (E) olağanüstü hallerde durumun gerektirdiği ölçüde SINIRLANABİLECEK haklar arasındadır; bunlar madde 15''in mutlak/dokunulmaz çekirdeği kapsamında değildir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('564c16b8-956c-4b39-9ecc-efa298aadb94', 'Seyahat özgürlüğü', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('564c16b8-956c-4b39-9ecc-efa298aadb94', 'Toplantı ve gösteri yürüyüşü düzenleme hakkı', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('564c16b8-956c-4b39-9ecc-efa298aadb94', 'Yaşama hakkı ve kişinin maddi-manevi varlığının bütünlüğü', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('564c16b8-956c-4b39-9ecc-efa298aadb94', 'Basın özgürlüğü', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('564c16b8-956c-4b39-9ecc-efa298aadb94', 'Mülkiyet hakkı', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e3cf87f5-2055-4a8f-83f2-e9ab2a7666d5', 'a761a66c-9aa8-45fe-a865-b4833c71d0b2', 'orta'::difficulty_level, 'Seçme ve seçilme hakkı ile siyasi parti kurma hakkı aşağıdaki hak kategorilerinden hangisinde yer alır?', 'Siyasi hakları sınıflandırır.', 'Seçme-seçilme hakkı ve siyasi parti kurma hakkı, vatandaşların devlet yönetimine katılımını sağlayan SİYASİ haklardır (D doğru). Bu haklar kişi hakları (A) gibi devletin müdahale etmemesini değil, sosyal-ekonomik haklar (B) gibi devletin doğrudan hizmet sunmasını da gerektirmez; doğal haklar (C) ve kültürel haklar (E) bu iki hakkı tanımlamak için kullanılan doğru kategoriler değildir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3cf87f5-2055-4a8f-83f2-e9ab2a7666d5', 'Kişi hakları (koruyucu haklar)', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3cf87f5-2055-4a8f-83f2-e9ab2a7666d5', 'Sosyal ve ekonomik haklar', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3cf87f5-2055-4a8f-83f2-e9ab2a7666d5', 'Doğal haklar', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3cf87f5-2055-4a8f-83f2-e9ab2a7666d5', 'Siyasi haklar', true, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e3cf87f5-2055-4a8f-83f2-e9ab2a7666d5', 'Kültürel haklar', false, 4);
insert into topics (id, subject_id, name, slug, kazanim_text, weight, order_index) values ('dafcd822-68ff-458c-b30b-00446742dcb2', 'a9ee39e3-e35c-4ff0-885a-4af773855d4d', 'Uluslararası Kuruluşlar', 'uluslararasi-kuruluslar', 'Türkiye''nin üye olduğu başlıca uluslararası kuruluşları ve amaçlarını açıklar.', 1.0, 5);
insert into topic_contents (topic_id, summary, content_md, example_question) values ('dafcd822-68ff-458c-b30b-00446742dcb2', 'Türkiye''nin kurucu üye veya üye olduğu başlıca uluslararası kuruluşlar (Birleşmiş Milletler, NATO, Avrupa Konseyi, Avrupa Birliği adaylık süreci) ve her birinin amacı, kuruluş tarihi bu konunun omurgasını oluşturur.', '## Birleşmiş Milletler (BM)
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('50dbc797-35ec-4344-966c-1bb5aa584551', 'dafcd822-68ff-458c-b30b-00446742dcb2', 'kolay'::difficulty_level, 'Türkiye, Birleşmiş Milletler (BM) örgütüne hangi statüde katılmıştır?', 'Türkiye''nin BM''deki konumunu bilir.', 'Türkiye, 1945''te kurulan Birleşmiş Milletler''e KURUCU ÜYE olarak katılmıştır (B doğru). A, C, D ve E ifadeleri Türkiye''nin BM''deki gerçek statüsünü yansıtmaz; Türkiye sonradan katılan bir üye değil, örgütün kuruluşunda yer alan devletlerden biridir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('50dbc797-35ec-4344-966c-1bb5aa584551', 'Gözlemci üye olarak', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('50dbc797-35ec-4344-966c-1bb5aa584551', 'Kurucu üye olarak', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('50dbc797-35ec-4344-966c-1bb5aa584551', 'Aday üye olarak', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('50dbc797-35ec-4344-966c-1bb5aa584551', 'Geçici üye olarak', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('50dbc797-35ec-4344-966c-1bb5aa584551', 'Türkiye BM''ye hiç üye olmamıştır', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('fe6a4ce2-c283-4d3f-8f06-538aeff6c15d', 'dafcd822-68ff-458c-b30b-00446742dcb2', 'orta'::difficulty_level, 'Avrupa İnsan Hakları Mahkemesi (AİHM) ile ilgili aşağıdakilerden hangisi doğrudur?', 'AİHM''in bağlı olduğu kuruluşu (Avrupa Konseyi) doğru tanır.', 'AİHM, Avrupa Birliği''ne değil Avrupa Konseyi''ne bağlı bir kuruluştur; bu iki örgüt (Avrupa Konseyi ve AB) birbirinden farklıdır ve sıkça karıştırılır (C doğru). A ve B, AİHM''i Avrupa Birliği veya NATO ile ilişkilendirdiği için yanlıştır. D ve E de yanlış kuruluşlarla ilişkilendirmedir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fe6a4ce2-c283-4d3f-8f06-538aeff6c15d', 'Avrupa Birliği''ne bağlı bir kuruluştur', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fe6a4ce2-c283-4d3f-8f06-538aeff6c15d', 'NATO''nun bir alt organıdır', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fe6a4ce2-c283-4d3f-8f06-538aeff6c15d', 'Avrupa Birliği''nden farklı bir kuruluş olan Avrupa Konseyi''ne bağlıdır', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fe6a4ce2-c283-4d3f-8f06-538aeff6c15d', 'Birleşmiş Milletler''in bir alt organıdır', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('fe6a4ce2-c283-4d3f-8f06-538aeff6c15d', 'İslam İşbirliği Teşkilatı''na bağlıdır', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('dbe441d0-b20e-44f2-8a77-cba9c8936bf1', 'dafcd822-68ff-458c-b30b-00446742dcb2', 'zor'::difficulty_level, 'Türkiye-Avrupa Birliği ilişkilerinin kronolojik gelişimiyle ilgili aşağıdaki sıralamalardan hangisi doğrudur?', 'Türkiye-AB ilişkilerinin kronolojisini bilir.', 'Doğru kronoloji: 1959''da AET''ye üyelik başvurusu → 1963''te Ankara Anlaşması ile ortaklık statüsü → 1996''da Gümrük Birliği''ne dahil olma → 1999 Helsinki Zirvesi''nde aday ülke statüsü kazanma → 2005''te tam üyelik müzakerelerinin başlaması (C doğru). Diğer seçenekler bu olayların sırasını veya içeriğini yanlış vermektedir; örneğin bazıları Türkiye''nin bugün tam üye olduğunu ima etmektedir ki bu YANLIŞTIR — Türkiye hâlâ tam üye değildir.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dbe441d0-b20e-44f2-8a77-cba9c8936bf1', '1999 Helsinki Zirvesi → 1963 Ankara Anlaşması → 1959 başvuru → 2005 tam üyelik', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dbe441d0-b20e-44f2-8a77-cba9c8936bf1', '1963 Ankara Anlaşması → 1959 başvuru → 2005 tam üyelik → 1999 aday statüsü', false, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dbe441d0-b20e-44f2-8a77-cba9c8936bf1', '1959 başvuru → 1963 Ankara Anlaşması → 1996 Gümrük Birliği → 1999 aday ülke statüsü → 2005 müzakerelerin başlaması', true, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dbe441d0-b20e-44f2-8a77-cba9c8936bf1', '1996 Gümrük Birliği → 1959 başvuru → 1999 tam üyelik → 2005 aday statüsü', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('dbe441d0-b20e-44f2-8a77-cba9c8936bf1', '2005 tam üyelik → 1999 aday statüsü → 1963 Ankara Anlaşması → 1959 başvuru', false, 4);
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('e389d72c-6716-43df-ada7-d2e62ec18521', 'dafcd822-68ff-458c-b30b-00446742dcb2', 'orta'::difficulty_level, 'Azerbaycan, Kazakistan, Kırgızistan, Özbekistan ve Türkiye arasındaki iş birliğini geliştirmeyi amaçlayan uluslararası kuruluş aşağıdakilerden hangisidir?', 'Türk Devletleri Teşkilatı''nın amacını ve üyelerini bilir.', 'Türk Devletleri Teşkilatı (eski adıyla Türk Konseyi), Türk dilli bağımsız devletler arasındaki iş birliğini geliştirmeyi amaçlayan bir kuruluştur (B doğru). NATO (A) bir savunma örgütüdür ve bu ülkelerin tamamını kapsamaz. Avrupa Konseyi (C) ve Avrupa Birliği (D) Avrupa odaklı kuruluşlardır, bu Orta Asya/Türk devletleriyle ilgili değildir. Birleşmiş Milletler (E) evrensel bir örgüttür, bu spesifik iş birliğini tanımlamaz.');
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e389d72c-6716-43df-ada7-d2e62ec18521', 'NATO', false, 0);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e389d72c-6716-43df-ada7-d2e62ec18521', 'Türk Devletleri Teşkilatı', true, 1);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e389d72c-6716-43df-ada7-d2e62ec18521', 'Avrupa Konseyi', false, 2);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e389d72c-6716-43df-ada7-d2e62ec18521', 'Avrupa Birliği', false, 3);
insert into question_choices (question_id, choice_text, is_correct, order_index) values ('e389d72c-6716-43df-ada7-d2e62ec18521', 'Birleşmiş Milletler', false, 4);
